create or replace function magick.is_magic_square (cells integer[]) returns boolean language sql immutable as $$ select array_length(cells, 1) = 9 and ( select count(distinct s) = 1 from unnest(array[ cells[1]+cells[2]+cells[3], cells[4]+cells[5]+cells[6], cells[7]+cells[8]+cells[9], cells[1]+cells[4]+cells[7], cells[2]+cells[5]+cells[8], cells[3]+cells[6]+cells[9], cells[1]+cells[5]+cells[9], cells[3]+cells[5]+cells[7] ]) as s ); $$;
